def trace(input_data):
    sess = TraceSession(
        algorithm="Convex Hull (Andrew's Monotone Chain)",
        input_data=input_data,
        pseudocode=[
            "Sort points by x, then y",
            "Build lower hull: keep only left turns",
            "Build upper hull: keep only left turns (in reverse)",
            "Combine lower (minus last) and upper (minus last)"
        ]
    )
    raw_pts = input_data["points"]
    pts = sorted(raw_pts, key=lambda p: (p[0], p[1]))
    # create visual points
    point_obj = sess.points("delivery_points", pts)
    # cross product helper (same as solve)
    def cross(o, a, b):
        return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

    with sess.step("Build lower hull"):
        lower = []
        for i, p in enumerate(pts):
            point_obj.highlight(i, role="candidate")
            while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
                sess.note(f"Pop {lower[-1]} (not a left turn)")
                lower.pop()
            lower.append(p)
            sess.note(f"Push {p}")
            if len(lower) >= 2:
                point_obj.add_segment(pts.index(lower[-2]), pts.index(lower[-1]))

    with sess.step("Build upper hull"):
        upper = []
        for i, p in enumerate(reversed(pts)):
            orig_idx = len(pts)-1 - i
            point_obj.highlight(orig_idx, role="candidate")
            while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
                sess.note(f"Pop {upper[-1]} (not a left turn)")
                upper.pop()
            upper.append(p)
            sess.note(f"Push {p}")
            if len(upper) >= 2:
                point_obj.add_segment(pts.index(upper[-2]), pts.index(upper[-1]))

    hull = lower[:-1] + upper[:-1]
    sess.result(hull)

    trace = sess.to_trace()
    for event in trace["events"]:
        op = event.get("op", "")
        targets = [t.get("id", "") for t in event.get("targets", [])]
        reason = event.get("reason", "")
        if op == "create" and "delivery points" in targets:
            event["code_line"] = 2
        elif op == "create" and "lower" in targets[0] if targets else False:
            event["code_line"] = 7
        elif op == "highlight" and role == "candidate" and "lower hull" in reason:
            event["code_line"] = 8
        elif op == "note" and "Pop" in reason:
            event["code_line"] = 10
        elif op == "note" and "Push" in reason and "lower" in reason:
            event["code_line"] = 11
        elif op == "highlight" and role == "candidate" and "upper hull" in reason:
            event["code_line"] = 13
        elif op == "note" and "Pop" in reason and "upper" in reason:
            event["code_line"] = 15
        elif op == "note" and "Push" in reason and "upper" in reason:
            event["code_line"] = 16
        elif event.get("role") == "answer" or "answer" in targets:
            event["code_line"] = 18
        else:
            event["code_line"] = 8  # fallback
    return trace

